func preflight() {
	var err error

	// prepare clean backup directory
	bud := os.Getenv(envGitBackupDir)

	// if path not provided, create one
	if bud == "" {
		bud, err = os.MkdirTemp(os.TempDir(), "sobabackup-*")
		if err != nil {
			panic(err)
		}

		_ = os.Setenv(envGitBackupDir, bud)

		return
	}

	_, err = os.Stat(filepath.Clean(bud))
	if os.IsNotExist(err) {
		if err = os.MkdirAll(filepath.Clean(bud), 0o700); err != nil {
			panic(err)
		}

		return
	}

	// clean out existing backup directory
	if err = removeContents(bud); err != nil {
		panic(err)
	}
}

func TestMain(m *testing.M) {
	preflight()

	code := m.Run()

	os.Exit(code)
}

func resetGlobals() {
	// retained for tests that historically reset package-level counters;
	// no globals to reset after the provider-count refactor.
}

func backupEnvironmentVariables() map[string]string {
	m := make(map[string]string)

	for _, e := range os.Environ() {
		if i := strings.Index(e, "="); i >= 0 {
			m[e[:i]] = e[i+1:]
		}
	}

	return m
}

func restoreEnvironmentVariables(input map[string]string) {
	for key, val := range input {
		_ = os.Setenv(key, val)
	}
}

func unsetEnvVarsExcept(exceptionList []string) {
}

func TestCheckProvidersFailureWhenNoneDefined(t *testing.T) {
	envBackup := backupEnvironmentVariables()
	defer restoreEnvironmentVariables(envBackup)

	preflight()
	resetGlobals()

	defer resetBackups()

	unsetEnvVarsExcept([]string{envPath})

	err := checkProvidersDefined()
	require.Error(t, err)

	require.Contains(t, err.Error(), "no providers defined")
}

func TestFailureIfGitBackupDirUndefined(t *testing.T) {
	envBackup := backupEnvironmentVariables()
	defer restoreEnvironmentVariables(envBackup)

	preflight()
	resetGlobals()

	defer resetBackups()

	unsetEnvVarsExcept([]string{envPath})

	_ = os.Setenv(envGitHubToken, "ABCD1234")

	defer os.Unsetenv(envGitHubToken)

	require.Errorf(t, Run(), "expected: %s undefined error", envGitBackupDir)
}

func TestGithubRepositoryBackupWithSingleOrgNoPersonal(t *testing.T) {
	skipUnlessLiveGitHub(t)

	_ = os.Unsetenv(envSobaWebHookURL)

	envBackup := backupEnvironmentVariables()
	defer restoreEnvironmentVariables(envBackup)

	preflight()
	if err != nil {
		logger.Printf("could not determine git version: %v", err)

		return
	}

	logger.Printf("git version: %s", strings.TrimSpace(string(out)))
}

func init() {
	logger = log.New(os.Stdout, fmt.Sprintf("%s: ", AppName), log.Lshortfile|log.LstdFlags)
}

func getLogLevel() int {
	sobaLogLevelEnv := os.Getenv(envSobaLogLevel)

	files, err := os.ReadDir(dfDir)
	require.NoError(t, err)
	require.Len(t, files, 3)

	r := regexp.MustCompile(`repo0\.[0-9]{14}\.(bundle|bundle\.invalid|lfs\.tar\.gz)$`)

	for _, file := range files {
		require.Regexp(t, r, file.Name(), fmt.Sprintf("unexpected file name: %s", file.Name()))
	}
}

func TestGithubRepositoryBackupWithInvalidToken(t *testing.T) {
	_ = os.Unsetenv(envSobaWebHookURL)

	envBackup := backupEnvironmentVariables()
	defer restoreEnvironmentVariables(envBackup)

	preflight()
	resetGlobals()

	defer resetBackups()

	// Unset Env Vars but exclude those defined
	unsetEnvVarsExcept([]string{envPath, envGitBackupDir, envGitHubToken, envGitHubCompare})

	// set invalid token
	_ = os.Setenv(envGitHubToken, "invalid")

	defer os.Unsetenv(envGitHubToken)

	githubHost, err := githosts.NewGitHubHost(githosts.NewGitHubHostInput{
		Caller:           AppName,
		APIURL:           os.Getenv(envGitHubAPIURL),
		DiffRemoteMethod: os.Getenv(envGitHubCompare),
		BackupDir:        os.TempDir(),
		Token:            os.Getenv(envGitHubToken),
		Orgs:             getOrgsListFromEnvVar(envGitHubOrgs),
		BackupsToRetain:  getBackupsToRetain(envGitHubBackups),
		SkipUserRepos:    envTrue(envGitHubSkipUserRepos),
		LogLevel:         getLogLevel(),
	})
	require.NoError(t, err)
	// skip if github.com is unreachable to avoid timeouts in restricted environments
	dialer := &net.Dialer{}

	conn, dialErr := dialer.DialContext(context.Background(), "tcp", "github.com:443")
	if dialErr != nil {
		t.Skipf("Skipping GitHub invalid credential test: %v", dialErr)
	}

	require.NoError(t, conn.Close())

	result := githubHost.Backup()
	require.NotNil(t, result.Error)
	// when connectivity is available GitHub returns \"Bad credentials\", but
	// other errors like request failures are acceptable in CI environments
	require.NotEmpty(t, errors.Unwrap(result.Error).Error())
	StartedAt  sobaTime                 `json:"started_at"`
	FinishedAt sobaTime                 `json:"finished_at"`
	Results    *[]ProviderBackupResults `json:"results,omitempty"`
}

func execProviderBackups() {
	failed := runProviderBackups()

	// If running one-shot (no scheduler) and any provider failed, surface a
	// non-zero exit. With a scheduler the next-run banner is enough.
	if job == nil && failed > 0 {
		os.Exit(1)
	}
}

func runProviderBackups() int {
}

func notify(backupResults BackupResults, succeeded int, failed int) {
	// optimistic create retryable http client
	errs := getResultsErrors(backupResults)

	// Check if we should only notify on failure
	notifyOnFailureOnly := envTrue(envSobaNotifyOnFailureOnly)

	// Skip notifications if success-only and no failures
	if notifyOnFailureOnly && failed == 0 {
		logger.Println("skipping notification (no failures)")

		return
	}

	webHookURL := os.Getenv(envSobaWebHookURL)
	if webHookURL != "" {
		err := sendWebhook(httpClient, sobaTime{
			Time: time.Now(),
			f:    time.RFC3339,
		}, backupResults, os.Getenv(envSobaWebHookURL), os.Getenv(envSobaWebHookFormat))
		if err != nil {
			logger.Printf("error sending webhook: %s", err)
		} else {
			logger.Println("webhook sent")
		}
	}

	ntfyURL := os.Getenv(envSobaNtfyURL)
	if ntfyURL != "" {
		sendNtfy(httpClient, ntfyURL, succeeded, failed, errs)
	}

	slackChannelID := os.Getenv(envSlackChannelID)
	if slackChannelID != "" {
		sendSlackMessage(slackChannelID, succeeded, failed, errs)
	}

